compile.workshop:
variables {
    global:
        0: value
}

rule ("included") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(value, 2);
    }
}

rule ("root") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(value, 1);
    }
}

